<script setup>
import { computed, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { jointStore as store, clone, evaluateItem, referenceText, resultKey, displayTime, PEOPLE } from '../../data/equipmentInspectionMock.js'
import TaskResults from './TaskResults.vue'
const props=defineProps({personId:{type:String,required:true},initialTaskId:{type:String,default:''}})
const mode=ref('my'),taskId=ref(''),pointIndex=ref(0),draftResults=ref({}),message=ref(''),error=ref('')
const myTasks=computed(()=>store.state.tasks.filter(task=>task.personId===props.personId))
const task=computed(()=>store.byId(store.state.tasks,taskId.value))
const point=computed(()=>task.value?.points[pointIndex.value])
const workingTask=computed(()=>task.value?{...task.value,results:draftResults.value}:null)
const validation=computed(()=>task.value?store.taskErrors(task.value,draftResults.value):[])
const progress=computed(()=>task.value?store.progress(task.value,draftResults.value):{requiredFilled:0,requiredTotal:0})
function select(id){taskId.value=id;pointIndex.value=0;draftResults.value=clone(store.byId(store.state.tasks,id)?.results || {});mode.value=task.value?.status==='已完成'?'done':'overview';message.value='';error.value=''}
watch(()=>props.initialTaskId,id=>{if(id)select(id)},{immediate:true})
function ensureResult(group,item){const key=resultKey(group,item);if(!draftResults.value[key])draftResults.value[key]={value:'',note:'',photos:[]};return draftResults.value[key]}
function begin(){try{store.startTask(taskId.value,props.personId);mode.value='point';error.value=''}catch(e){error.value=e.message}}
function save(){try{store.saveTaskDraft(taskId.value,draftResults.value,props.personId);draftResults.value=clone(task.value.results);message.value=`已暂存本次填写 · ${displayTime(store.now())}`;error.value='';return true}catch(e){error.value=e.message;return false}}
function review(){if(save())mode.value='review'}
function submit(){try{store.submitTask(taskId.value,draftResults.value,props.personId);draftResults.value=clone(task.value.results);mode.value='done';message.value='本次检查已提交，巡检记录与电子台账已引用同一份原始结果。';error.value='';ElMessage.success('任务已完成；检查结果和是否超期分别保留')}catch(e){error.value=e.message}}
async function attach(file,group,item){
  const raw=file.raw
  if(!raw || !['image/png','image/jpeg','image/webp'].includes(raw.type) || raw.size>1024*1024){error.value='仅接受 PNG / JPEG / WebP 图片，每张不超过1MB；附件只保存在本地浏览器。';return}
  const result=ensureResult(group,item)
  if(result.photos.length>=3){error.value='每项最多保留3张本地演示图片';return}
  try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(raw)});result.photos.push({name:raw.name,dataUrl});if(item.type==='照片')result.value=result.photos.map(photo=>photo.name).join('、');error.value=''}catch{error.value='本地图片读取失败，请重新选择'}
}
function removePhoto(group,item,index){const result=ensureResult(group,item);result.photos.splice(index,1);if(item.type==='照片')result.value=result.photos.map(photo=>photo.name).join('、')}
const tone=decision=>decision==='异常'?'danger':decision==='正常'?'success':'info'
</script>
<template>
  <section class="mobile-shell">
    <header class="mobile-header"><strong>移动巡检交互演示</strong><small>当前浏览器内 · {{ PEOPLE.find(person=>person.id===personId)?.name }}</small></header>
    <p class="scope">Mock · 未上传服务端，不提供离线同步。检查值由本人逐项填写；异常不阻止保存真实读数。</p>
    <template v-if="mode==='my'"><h2>我的任务</h2><p class="muted">选择任务，查看当前检查点并开始现场填写。</p><article v-for="row in myTasks" :key="row.id" class="my-task"><div class="between"><strong>{{ row.planName }}</strong><el-tag size="small">{{ row.status }}</el-tag></div><p>{{ row.date }} · {{ row.slot.start }}—{{ row.slot.end }}</p><p class="muted">{{ row.points.length }} 个检查点 · {{ store.taskSummary(row) }} · {{ store.timeStatus(row) }}</p><el-button type="primary" plain @click="select(row.id)">{{ row.status==='已完成'?'查看已提交结果':'进入本次任务' }}</el-button></article><el-empty v-if="!myTasks.length" description="当前演示身份没有任务" :image-size="70" /></template>
    <template v-else-if="task"><div class="between task-title"><el-button link @click="mode='my';error='';message=''">返回我的任务</el-button><el-tag size="small">{{ task.status }}</el-tag></div><h2>{{ task.planName }}</h2><p class="muted">{{ task.date }} {{ task.slot.start }}—{{ task.slot.end }} · {{ task.rule.name }} V{{ task.rule.version }}</p>
      <template v-if="mode==='overview'"><p class="scope">本次有 {{ task.points.length }} 个检查点。{{ task.status==='待执行'?'所有检查项未填写，不预设正常，也不复制上次读数。':'继续本人已暂存的本次填写。' }}</p><article v-for="(row,index) in task.points" :key="row.id" class="my-task"><strong>{{ index+1 }}. {{ row.space.name }}</strong><p class="muted">{{ row.space.spacePath }}</p><p>{{ row.groups.map(group=>group.object.name).join('、') }}</p></article><el-button type="primary" class="full-button" @click="begin">{{ task.status==='待执行'?'开始检查':'继续本次检查' }}</el-button></template>
      <template v-if="mode==='point' && point"><div class="progress"><strong>必检 {{ progress.requiredFilled }} / {{ progress.requiredTotal }}</strong><span>检查点 {{ pointIndex+1 }} / {{ task.points.length }}</span></div><el-progress :percentage="progress.requiredTotal?Math.round(progress.requiredFilled/progress.requiredTotal*100):0" :show-text="false" /><el-select v-model="pointIndex" aria-label="当前检查点" class="point-select"><el-option v-for="(row,index) in task.points" :key="row.id" :value="index" :label="`${index+1}. ${row.space.name}`" /></el-select><h3>{{ point.space.name }}</h3><p class="muted">{{ point.space.location }} · {{ point.space.spacePath }}</p>
        <article v-for="group in point.groups" :key="`${group.id}-${group.object.id}`" class="object-card"><div class="object-header"><strong>{{ group.object.name }}</strong><small>{{ group.object.code }} · {{ group.name }}</small></div>
          <div v-for="item in group.items" :key="item.id" class="check-item"><label :for="`input-${group.object.id}-${item.id}`">{{ item.name }} <span v-if="item.required" class="required">必检</span><small v-else>选填</small></label><p class="method">{{ item.method || '按现场实际情况填写' }}</p>
            <el-input v-if="item.type==='数值'" :id="`input-${group.object.id}-${item.id}`" v-model="ensureResult(group,item).value" :aria-label="`${group.object.name} ${item.name}`" inputmode="decimal" placeholder="请输入本次实际读数"><template #append>{{ item.unit }}</template></el-input>
            <el-select v-else-if="item.type==='状态'" :id="`input-${group.object.id}-${item.id}`" v-model="ensureResult(group,item).value" :aria-label="`${group.object.name} ${item.name}`" clearable placeholder="请选择现场状态"><el-option v-for="option in item.options" :key="option" :value="option" /></el-select>
            <el-input v-else-if="item.type==='文本'" :id="`input-${group.object.id}-${item.id}`" v-model="ensureResult(group,item).value" :aria-label="`${group.object.name} ${item.name}`" type="textarea" :rows="2" maxlength="1000" placeholder="填写现场观察" />
            <el-upload v-else :auto-upload="false" :show-file-list="false" accept="image/png,image/jpeg,image/webp" :on-change="file=>attach(file,group,item)"><el-button>选择本地照片</el-button></el-upload>
            <div class="judgment"><el-tag size="small" :type="tone(evaluateItem(item,ensureResult(group,item)))">{{ evaluateItem(item,ensureResult(group,item)) }}</el-tag><small>{{ referenceText(item) }}</small></div>
            <div v-if="evaluateItem(item,ensureResult(group,item))==='异常'" class="exception"><strong>异常展开 · 原始值允许保存</strong><p>{{ item.guidance || '请报告并按已批准预案处置。' }}</p><label>异常说明{{ item.exceptionNote?'（必填）':'（选填）' }}</label><el-input v-model="ensureResult(group,item).note" :aria-label="`${group.object.name} ${item.name}异常说明`" type="textarea" :rows="3" maxlength="1000" placeholder="记录现场事实、已报告情况等，随原始结果保存" /><el-upload :auto-upload="false" :show-file-list="false" accept="image/png,image/jpeg,image/webp" :on-change="file=>attach(file,group,item)"><el-button size="small">补充本地照片{{ item.exceptionPhoto?'（必填）':'（选填）' }}</el-button></el-upload><small>每张不超过1MB，最多3张；不上传真实现场敏感资料。</small></div>
            <div v-if="ensureResult(group,item).photos.length" class="photos"><div v-for="(photo,index) in ensureResult(group,item).photos" :key="index"><img :src="photo.dataUrl" :alt="photo.name" /><el-button link type="danger" @click="removePhoto(group,item,index)">移除照片</el-button></div></div>
          </div>
        </article>
        <div class="actions"><el-button :disabled="pointIndex===0" @click="pointIndex--">上一个检查点</el-button><el-button v-if="pointIndex<task.points.length-1" type="primary" @click="pointIndex++">下一个检查点</el-button></div><div class="actions bottom"><el-button @click="save">暂存本次填写</el-button><el-button type="primary" @click="review">核对全部结果</el-button></div><p class="muted">未暂存的输入在关闭预览后不保留；暂存是本地演示保存，不是联网同步。</p>
      </template>
      <template v-if="mode==='review'"><h3 class="section">核对提交</h3><p class="scope">执行状态、检查结果和时间状态分别保存。异常读数可以提交，所需异常说明 / 照片必须齐全。</p><div v-if="validation.length" class="errors" role="alert"><strong>暂不能提交：</strong><ul><li v-for="item in validation" :key="item.key">{{ item.message }}</li></ul></div><TaskResults :task="workingTask" /><div class="actions bottom"><el-button @click="mode='point'">返回补充填写</el-button><el-button type="primary" :disabled="Boolean(validation.length)" @click="submit">确认提交本次检查</el-button></div></template>
      <template v-if="mode==='done'"><div class="done"><h3>本次任务已完成</h3><p>{{ store.taskSummary(task) }} · {{ store.timeStatus(task) }}</p><p>实际提交：{{ displayTime(task.submittedAt) }}</p></div><p class="scope">提交后只读；处置完成与工单流转不在本次演示范围。</p><router-link :to="{path:'/inspection/records',query:{task:task.id}}"><el-button type="primary" plain class="full-button">查看同源巡检记录</el-button></router-link><TaskResults :task="task" /></template>
    </template>
    <p v-if="message" class="saved" role="status">{{ message }}</p><p v-if="error" class="errors" role="alert">{{ error }}</p><el-alert v-if="store.notice.persistence" :title="store.notice.persistence" type="warning" :closable="false" />
  </section>
</template>
<style scoped>
.mobile-shell{width:min(100%,420px);margin:0 auto;background:var(--ez-card-bg);font-size:14px;line-height:1.7;color:var(--ez-text)}.mobile-header{padding:14px 16px;background:var(--ez-primary-bg);border-radius:12px;color:var(--ez-primary);display:flex;flex-direction:column}.mobile-header small{font-size:12px;margin-top:4px}h2{font-size:18px;margin:12px 0}h3{font-size:16px}.scope{font-size:12px;background:var(--ez-fill-light);padding:12px;border-radius:8px;margin:12px 0;color:var(--ez-text-secondary)}.muted,small{font-size:12px;color:var(--ez-text-secondary)}.my-task{border:1px solid var(--ez-border);border-radius:12px;padding:16px;margin:14px 0}.my-task p{margin:8px 0}.between,.progress{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}.progress{margin:18px 0 8px;font-size:12px}.progress strong{color:var(--ez-primary)}.task-title{margin:16px 0}.point-select{width:100%;margin:20px 0 12px}.object-card{border:1px solid var(--ez-border);border-radius:12px;margin:16px 0;padding:16px}.object-header{display:flex;flex-direction:column;border-bottom:1px solid var(--ez-border);padding-bottom:12px}.check-item{padding:16px 0;border-bottom:1px solid var(--ez-border-light)}.check-item:last-child{border:0;padding-bottom:0}.check-item label{display:block;margin-bottom:8px;font-weight:500}.check-item :deep(.el-select){width:100%}.check-item :deep(.el-input__wrapper){min-height:42px}.method{font-size:12px;color:var(--ez-text-secondary);margin-bottom:8px}.required{font-size:12px;color:var(--ez-danger);margin-left:4px}.judgment{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.judgment small{color:var(--ez-warning-text)}.exception{background:var(--el-color-warning-light-9);border-radius:8px;padding:12px;margin-top:12px}.exception strong{color:var(--ez-warning-text);font-size:13px}.exception p,.exception label,.exception :deep(.el-upload){margin:10px 0}.exception small{display:block}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.actions :deep(.el-button + .el-button){margin-left:0}.bottom{border-top:1px solid var(--ez-border);padding-top:16px;margin:20px 0 12px}.full-button{width:100%;min-height:42px}.errors{color:var(--ez-danger);background:var(--el-color-danger-light-9);padding:14px;border-radius:8px;margin:16px 0;overflow-wrap:anywhere}.errors ul{padding-left:18px}.saved{color:var(--ez-success);background:var(--el-color-success-light-9);padding:12px;border-radius:8px;margin-top:16px}.done{padding:20px;background:var(--ez-primary-bg);border-radius:12px;margin:20px 0}.done p{margin-top:8px}.section{margin:20px 0 12px}.photos{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.photos div{display:flex;flex-direction:column;max-width:110px}.photos img{width:100px;height:80px;object-fit:cover;border-radius:6px}
</style>
